css:
/* =========================================================
   ЛЭМП ЛИГАЛ — прототип главной страницы (v2, акцент на стартапы)
   Цвета и шрифт — по брендбуку. Сайт намеренно в одной светлой теме.
   Пометки [уточнить] выделены пунктиром (класс .todo) —
   их можно скрыть кнопкой «Скрыть пометки» внизу справа.
   ========================================================= */
:root{
  /* Брендбук */
  --lamp-orange:#F28C28;   /* акцент, действие */
  --graphite:#24282B;      /* текст, заголовки */
  --tech-blue:#7FAFC7;     /* интерфейсы, графика */
  --pale-blue:#DDECF2;     /* фоны разделов */
  --warm-neutral:#F5F4F0;  /* основной фон */
  --warm-gray:#DAD7D0;     /* границы, вторичный текст */
  --soft-orange:#F9D5B0;   /* тёплые акценты */
  /* Производные */
  --white:#FFFFFF;
  --text-2:#5F5B54;
  --orange-ink:#B85F0E;    /* оранжевый для мелкого текста — контрастнее */
  --font:"Manrope",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  --r-lg:28px; --r-md:18px; --r-sm:12px;
  --max:1200px;
  color-scheme:light;
}
*{box-sizing:border-box}
[hidden]{display:none!important}
html{scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important;animation:none!important}}
body{margin:0;background:var(--warm-neutral);color:var(--graphite);font-family:var(--font);font-size:16px;line-height:1.55;-webkit-font-smoothing:antialiased}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:60;background:var(--warm-neutral)}
h1,h2,h3{margin:0;line-height:1.12;letter-spacing:-.02em;text-wrap:balance}
p{margin:0}
a{color:inherit}
:focus-visible{outline:2px solid var(--lamp-orange);outline-offset:3px;border-radius:6px}

.container{max-width:var(--max);margin:0 auto;
  padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px))}
section{padding-block:88px}
.section-head{display:grid;gap:14px;max-width:720px;margin-bottom:44px}
.eyebrow{font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--orange-ink)}
h2{font-size:clamp(28px,4vw,42px);font-weight:800}
.lead{font-size:18px;color:var(--text-2);max-width:62ch}

/* Кнопки */
.btn{display:inline-flex;align-items:center;gap:10px;border:0;cursor:pointer;font:inherit;font-weight:700;font-size:16px;
  padding:16px 26px;border-radius:999px;text-decoration:none;transition:transform .15s ease,background .15s ease}
.btn-primary{background:var(--lamp-orange);color:var(--graphite)}
.btn-primary:hover{background:#F59B42;transform:translateY(-1px)}
.btn-ghost{background:transparent;color:var(--graphite);border:1.5px solid var(--graphite)}
.btn-ghost:hover{background:var(--graphite);color:var(--white)}
.btn .arr{transition:transform .15s ease}
.btn:hover .arr{transform:translateX(3px)}

/* Пометки для команды */
.todo{background:repeating-linear-gradient(90deg,transparent 0 6px,rgba(242,140,40,.12) 6px 12px);
  border:1px dashed var(--lamp-orange);border-radius:6px;padding:0 6px;font-size:.88em;color:var(--orange-ink);font-weight:600}
body.clean .todo{display:none}

/* ---------- Шапка ---------- */
.site-header{position:sticky;top:env(safe-area-inset-top,0px);z-index:50;background:rgba(245,244,240,.88);backdrop-filter:blur(10px);border-bottom:1px solid transparent;transition:border-color .2s}
.site-header.scrolled{border-bottom-color:var(--warm-gray)}
.header-row{display:flex;align-items:center;gap:28px;height:72px}
.logo{display:flex;align-items:center;gap:10px;text-decoration:none;font-weight:800;font-size:19px;letter-spacing:-.01em;flex-shrink:0}
.logo svg{width:30px;height:30px}
.slogan-top{font-size:12px;color:var(--text-2);border-left:1px solid var(--warm-gray);padding-left:14px;max-width:180px;line-height:1.3}
.nav{display:flex;gap:20px;margin-left:auto}
.nav a{text-decoration:none;font-weight:500;font-size:15px;color:var(--text-2);white-space:nowrap}
.header-cta{white-space:nowrap}
.nav a:hover{color:var(--graphite)}
.header-cta{padding:11px 20px;font-size:15px}
.menu-btn{display:none;margin-left:auto;background:none;border:1.5px solid var(--graphite);border-radius:999px;font:inherit;font-weight:700;font-size:14px;padding:8px 16px;cursor:pointer}
@media (max-width:1240px){.slogan-top{display:none}}
@media (max-width:1020px){
  .nav{display:none;position:absolute;top:72px;left:0;right:0;flex-direction:column;gap:0;background:var(--warm-neutral);border-bottom:1px solid var(--warm-gray);
    padding:8px max(20px,env(safe-area-inset-right,0px)) 16px max(20px,env(safe-area-inset-left,0px))}
  .nav.open{display:flex}
  .nav a{padding:12px 0;border-bottom:1px solid var(--warm-gray);font-size:17px}
  .menu-btn{display:block}
  .header-cta{display:none}
}

/* ---------- 1. Первый экран ---------- */
.hero{padding-block:56px 72px}
.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:48px;align-items:center}
.hero-copy{display:grid;gap:22px;min-width:0}
.hero h1{font-size:clamp(40px,6.2vw,76px);font-weight:800;letter-spacing:-.035em}
.hero h1 em{font-style:normal;color:var(--lamp-orange)}
.hero .lead{font-size:19px}
.theses{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:6px}
.thesis{background:var(--white);border-radius:var(--r-sm);padding:14px 16px;font-size:14px;color:var(--text-2);min-width:0}
.thesis b{display:block;color:var(--graphite);font-size:15px;margin-bottom:4px}
.cta-row{display:flex;flex-wrap:wrap;align-items:center;gap:16px 22px;margin-top:6px}
.micro{font-size:14px;color:var(--text-2);max-width:36ch}

/* Визуал: лампа светит на путь стартапа */
.hero-visual{position:relative;border-radius:var(--r-lg);background:var(--graphite);color:var(--warm-neutral);padding:32px 28px 28px;overflow:hidden;min-width:0}
.hero-visual::before{content:"";position:absolute;inset:0;
  background-image:radial-gradient(rgba(245,244,240,.14) 1px,transparent 1.4px);background-size:14px 14px;
  -webkit-mask-image:linear-gradient(160deg,#000 10%,transparent 70%);mask-image:linear-gradient(160deg,#000 10%,transparent 70%)}
.hero-visual .glow{position:absolute;width:420px;height:420px;left:-120px;top:-160px;border-radius:50%;
  background:radial-gradient(circle,rgba(242,140,40,.55),rgba(242,140,40,0) 65%)}
.hero-visual .glow2{position:absolute;width:360px;height:360px;right:-160px;bottom:-160px;border-radius:50%;
  background:radial-gradient(circle,rgba(127,175,199,.45),rgba(127,175,199,0) 65%)}
.hv-head{position:relative;display:flex;align-items:center;gap:12px;margin-bottom:26px}
.hv-head svg{width:40px;height:40px}
.hv-head span{font-size:13px;letter-spacing:.12em;text-transform:uppercase;opacity:.75;font-weight:600}
.path{position:relative;list-style:none;margin:0;padding:0;display:grid;gap:4px}
.path::before{content:"";position:absolute;left:11px;top:14px;bottom:14px;width:2px;background:linear-gradient(var(--lamp-orange),var(--tech-blue))}
.path li{position:relative;display:grid;grid-template-columns:24px 1fr;gap:16px;align-items:start;padding:10px 0}
.path .pt{width:24px;height:24px;border-radius:50%;background:var(--graphite);border:2px solid var(--c,var(--lamp-orange));display:grid;place-items:center}
.path .pt::after{content:"";width:8px;height:8px;border-radius:50%;background:var(--c,var(--lamp-orange))}
.path b{display:block;font-size:17px}
.path small{display:block;font-size:14px;opacity:.72;margin-top:2px}
.path li:nth-child(2){--c:#D9985A}.path li:nth-child(3){--c:#B5A48A}.path li:nth-child(4){--c:var(--tech-blue)}
@media (max-width:960px){.hero-grid{grid-template-columns:1fr}.hero-visual{max-width:560px}}
@media (max-width:640px){.theses{grid-template-columns:1fr}}

/* ---------- 1а. Полоса доверия ---------- */
.trust{padding-block:28px;border-block:1px solid var(--warm-gray)}
.trust-row{display:flex;flex-wrap:wrap;align-items:center;gap:16px 40px}
.trust-label{font-size:13px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--text-2)}
.trust-item{display:flex;align-items:center;gap:10px;font-weight:700;color:var(--graphite);opacity:.85}
.trust-logo{height:34px;width:auto;display:block}
.trust-stats{display:flex;flex-wrap:wrap;gap:12px 28px}
.stat{font-size:14px;color:var(--text-2)}
.stat b{font-size:22px;font-weight:800;color:var(--graphite);margin-right:6px;font-variant-numeric:tabular-nums}
@media (max-width:900px){.trust-stats{margin-left:0}}
.logo-ph{width:34px;height:34px;border-radius:10px;background:var(--pale-blue);display:grid;place-items:center;font-size:12px;font-weight:800;color:var(--graphite)}

/* ---------- 2. Стадии ---------- */
.stages{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.stage{background:var(--white);border-radius:var(--r-md);padding:26px 22px 24px;display:grid;align-content:start;gap:14px;position:relative;min-width:0}
.stage::before{content:"";position:absolute;left:22px;right:22px;top:0;height:4px;border-radius:0 0 4px 4px;background:var(--c)}
.stage .num{font-size:13px;font-weight:700;color:var(--text-2);font-variant-numeric:tabular-nums}
.stage h3{font-size:22px;font-weight:800}
.stage ul{list-style:none;margin:0;padding:0;display:grid;gap:12px}
.stage li{font-size:15px;color:var(--text-2);padding-left:18px;position:relative}
.stage li::before{content:"";position:absolute;left:0;top:.62em;width:7px;height:7px;border-radius:50%;background:var(--c)}
.stage:nth-child(1){--c:var(--lamp-orange)}.stage:nth-child(2){--c:#E59A52}.stage:nth-child(3){--c:#A9B4B2}.stage:nth-child(4){--c:var(--tech-blue)}
.after-note{margin-top:28px;display:flex;flex-wrap:wrap;gap:12px 20px;align-items:center;font-size:16px}
.after-note a{font-weight:700;color:var(--orange-ink);text-underline-offset:3px}
@media (max-width:980px){.stages{grid-template-columns:repeat(2,1fr)}}
@media (max-width:560px){.stages{grid-template-columns:1fr}}

/* ---------- 3. Услуги ---------- */
.services-bg{background:var(--pale-blue)}
.svc-wrap{display:grid;grid-template-columns:.8fr 1.2fr;gap:56px;align-items:start}
.svc-aside{position:sticky;top:110px;display:grid;gap:14px}
.svc-list{display:grid;gap:10px;min-width:0}
.svc-group{font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--text-2);margin:14px 0 2px}
.svc-group:first-child{margin-top:0}
details.svc{background:var(--white);border-radius:var(--r-md);transition:box-shadow .2s}
details.svc[open]{box-shadow:0 10px 30px -18px rgba(36,40,43,.35)}
details.svc summary{list-style:none;cursor:pointer;display:grid;grid-template-columns:1fr auto;gap:4px 18px;padding:20px 22px;align-items:center}
details.svc summary::-webkit-details-marker{display:none}
.svc-title{font-size:19px;font-weight:700}
.svc-short{grid-column:1;font-size:15px;color:var(--text-2)}
.plus{grid-row:1/span 2;grid-column:2;width:36px;height:36px;border-radius:50%;background:var(--warm-neutral);display:grid;place-items:center;transition:transform .2s,background .2s}
.plus svg{width:14px;height:14px}
details.svc[open] .plus{transform:rotate(45deg);background:var(--soft-orange)}
.svc-body{padding:0 22px 22px;color:var(--text-2);max-width:62ch;display:grid;gap:10px}
.grant-banner{margin-top:18px;border-radius:var(--r-md);background:var(--soft-orange);color:var(--graphite);padding:22px;display:flex;flex-wrap:wrap;gap:14px 20px;align-items:center;justify-content:space-between}
.grant-banner p{max-width:46ch}
.grant-banner b{color:var(--graphite)}
@media (max-width:900px){.svc-wrap{grid-template-columns:1fr;gap:28px}.svc-aside{position:static}}

/* ---------- 4. Как работаем ---------- */
.principles{display:grid;grid-template-columns:repeat(3,1fr);gap:36px 40px}
.principle{display:grid;gap:10px;align-content:start;padding-top:18px;border-top:1px solid var(--warm-gray);min-width:0}
.principle .i{font-size:13px;font-weight:700;color:var(--orange-ink);font-variant-numeric:tabular-nums}
.principle h3{font-size:20px;font-weight:700}
.principle p{color:var(--text-2);font-size:15px}
.principle.key{border-top:2px solid var(--lamp-orange)}
.closing{margin-top:52px;font-size:clamp(20px,2.4vw,26px);font-weight:700;max-width:30ch;letter-spacing:-.01em}
@media (max-width:900px){.principles{grid-template-columns:repeat(2,1fr)}}
@media (max-width:560px){.principles{grid-template-columns:1fr}}

/* ---------- 5. Кейсы ---------- */
.cases{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.case{background:var(--white);border-radius:var(--r-md);padding:26px 24px;display:grid;gap:18px;align-content:start;min-width:0}
.case-tag{justify-self:start;font-size:12px;font-weight:700;padding:5px 12px;border-radius:999px;background:var(--soft-orange);color:var(--graphite)}
.case:nth-child(2) .case-tag{background:var(--pale-blue)}
.case:nth-child(3) .case-tag{background:var(--warm-gray)}
.case h3{font-size:21px;font-weight:800}
.case dl{margin:0;display:grid;gap:12px}
.case dt{font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--text-2)}
.case dd{margin:2px 0 0;font-size:15px}
.nda{margin-top:22px;font-size:14px;color:var(--text-2)}
@media (max-width:980px){.cases{grid-template-columns:1fr;max-width:640px}}

/* ---------- 6. Форматы ---------- */
.formats-bg{background:var(--white)}
.formats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.format{border:1.5px solid var(--warm-gray);border-radius:var(--r-md);padding:28px 24px;display:grid;gap:14px;align-content:start;min-width:0}
.format.feat{border-color:var(--graphite);background:var(--graphite);color:var(--warm-neutral)}
.format.feat .f-when{color:rgba(245,244,240,.75)}
.format h3{font-size:22px;font-weight:800}
.f-sub{font-weight:700;color:var(--orange-ink)}
.format.feat .f-sub{color:var(--lamp-orange)}
.f-when{font-size:15px;color:var(--text-2)}
.f-price{margin-top:6px;font-weight:700;font-size:17px}
.price-note{margin-top:20px;color:var(--text-2);max-width:62ch}
.steps{margin-top:56px;display:grid;grid-template-columns:repeat(5,1fr);gap:0;counter-reset:s;list-style:none;padding:0}
.steps li{position:relative;padding:44px 18px 0 0;display:grid;gap:6px;align-content:start;min-width:0}
.steps li::before{counter-increment:s;content:counter(s);position:absolute;left:0;top:0;width:30px;height:30px;border-radius:50%;background:var(--lamp-orange);display:grid;place-items:center;font-weight:800;font-size:14px}
.steps li::after{content:"";position:absolute;left:38px;right:8px;top:14px;height:2px;background:var(--warm-gray)}
.steps li:last-child::after{display:none}
.steps b{font-size:16px}
.steps span{font-size:14px;color:var(--text-2)}
.steps-cta{margin-top:36px}
@media (max-width:980px){.formats{grid-template-columns:1fr;max-width:640px}.steps{grid-template-columns:1fr;gap:22px}.steps li{padding:0 0 0 46px}.steps li::after{display:none}}

/* ---------- 7. Команда ---------- */
.team{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}
.member{display:grid;gap:12px;align-content:start;min-width:0}
.photo{aspect-ratio:4/5;max-width:100%;border-radius:var(--r-md);background:
  radial-gradient(circle at 50% 38%,var(--warm-neutral) 0 17%,transparent 17.5%),
  radial-gradient(ellipse at 50% 100%,var(--warm-neutral) 0 38%,transparent 38.5%),var(--pale-blue);
  display:grid;align-items:end;justify-items:start;padding:12px}
.member:nth-child(2) .photo{background-color:var(--soft-orange)}
.member:nth-child(3) .photo{background-color:var(--warm-gray)}
.member:nth-child(4) .photo{background-color:var(--pale-blue)}
.member h3{font-size:18px;font-weight:700}
.role{font-size:14px;font-weight:700;color:var(--orange-ink)}
.spec{font-size:14px;color:var(--text-2)}
.member a{font-size:14px;font-weight:600}
@media (max-width:1180px){.team{grid-template-columns:repeat(3,1fr);gap:20px 16px}}
@media (max-width:700px){.team{grid-template-columns:repeat(2,1fr)}}
.photo.has-img{padding:0;overflow:hidden;background:var(--warm-gray)}
.photo img{width:100%;height:100%;object-fit:cover;display:block}

/* ---------- 4а. Мы в сообществе (фото) ---------- */
.gallery{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:210px;gap:12px}
.tile{position:relative;margin:0;border-radius:var(--r-md);overflow:hidden;background:var(--warm-gray);min-width:0}
.tile img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .4s ease}
.tile:hover img{transform:scale(1.03)}
.tile figcaption{position:absolute;left:0;right:0;bottom:0;padding:40px 16px 14px;color:#fff;font-size:14px;font-weight:600;line-height:1.35;
  background:linear-gradient(transparent,rgba(20,22,24,.78))}
.tile figcaption small{display:block;font-weight:500;opacity:.8;font-size:12.5px}
.t-big{grid-column:span 2;grid-row:span 2}
.t-tall{grid-row:span 2}
.t-text{grid-column:1/-1;background:var(--pale-blue);color:var(--graphite);padding:28px 32px;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:20px 32px}
.t-text p{font-size:clamp(18px,1.8vw,22px);font-weight:600;line-height:1.35;letter-spacing:-.01em;max-width:52ch}
.t-text b{color:var(--graphite);font-weight:800}
@media (max-width:900px){
  .gallery{grid-template-columns:repeat(2,1fr);grid-auto-rows:auto}
  .tile{aspect-ratio:4/5;grid-row:auto!important}
  .t-big{grid-column:span 2;aspect-ratio:3/2}
  .t-text{aspect-ratio:auto}
}

/* ---------- 8. С кем работаем ---------- */
.fit-bg{background:var(--graphite);color:var(--warm-neutral)}
.fit-bg .eyebrow{color:var(--lamp-orange)}
.fit-bg .lead{color:rgba(245,244,240,.75)}
.fit{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.fit-item{border-radius:var(--r-md);padding:24px 22px;background:rgba(245,244,240,.06);border:1px solid rgba(245,244,240,.12);display:grid;gap:10px;align-content:start;min-width:0}
.fit-item .dot{width:12px;height:12px;border-radius:50%;background:var(--c)}
.fit-item h3{font-size:19px;font-weight:700}
.fit-item p{font-size:15px;color:rgba(245,244,240,.72)}
.fit-item:nth-child(1){--c:var(--lamp-orange)}.fit-item:nth-child(2){--c:#E59A52}.fit-item:nth-child(3){--c:#A9B4B2}.fit-item:nth-child(4){--c:var(--tech-blue)}
.fit-close{margin-top:36px;display:flex;flex-wrap:wrap;gap:14px 24px;align-items:center;font-size:18px}
.fit-bg .btn-ghost{color:var(--warm-neutral);border-color:var(--warm-neutral)}
.fit-bg .btn-ghost:hover{background:var(--warm-neutral);color:var(--graphite)}
@media (max-width:980px){.fit{grid-template-columns:repeat(2,1fr)}}
@media (max-width:560px){.fit{grid-template-columns:1fr}}

/* ---------- Баннер закреплённой статьи ---------- */
.promo-bar{background:var(--pale-blue);color:var(--graphite);font-size:14px;border-bottom:1px solid #C9DDE6}
.promo-bar .container{display:flex;align-items:center;gap:12px;min-height:44px;padding-block:8px}
.promo-bar .tag{background:var(--white);color:var(--graphite);font-weight:800;font-size:11px;letter-spacing:.08em;text-transform:uppercase;padding:3px 8px;border-radius:99px;flex-shrink:0}
.promo-bar a{color:var(--graphite);font-weight:600;text-underline-offset:3px;min-width:0}
.promo-bar a:hover{color:var(--orange-ink)}
.promo-close{margin-left:auto;background:none;border:0;color:inherit;opacity:.7;font-size:16px;cursor:pointer;padding:4px 6px;flex-shrink:0}

/* ---------- 9. Блог ---------- */
.blog-filter{display:flex;flex-wrap:wrap;gap:8px;margin:-16px 0 28px}
.blog-filter button{font:inherit;font-size:14px;font-weight:600;padding:8px 14px;border-radius:999px;border:1.5px solid var(--warm-gray);background:transparent;color:var(--graphite);cursor:pointer}
.blog-filter button[aria-pressed="true"]{background:var(--graphite);border-color:var(--graphite);color:var(--warm-neutral)}
.featured{display:grid;grid-template-columns:1.15fr .85fr;background:var(--graphite);color:var(--warm-neutral);border-radius:var(--r-lg);overflow:hidden;margin-bottom:16px;text-decoration:none}
.featured-copy{padding:clamp(24px,4vw,44px);display:grid;gap:16px;align-content:start;min-width:0}
