.fsrc small{display:block;font-weight:500;color:var(--text-2);font-size:13px}
.fdown{justify-self:center;width:2px;height:22px;background:var(--warm-gray);position:relative}
.fdown::after{content:"";position:absolute;left:-4px;bottom:-2px;border:5px solid transparent;border-top-color:var(--warm-gray)}
.fgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.fnode{padding:12px 14px;border-radius:var(--r-sm);border:1.5px solid var(--warm-gray);font-size:14px;font-weight:700;display:grid;gap:4px}
.fnode small{font-weight:500;color:var(--text-2);font-size:12.5px}
.fdoc{display:inline-block;justify-self:start;font-size:11px;font-weight:700;background:var(--pale-blue);color:#2F5566;padding:2px 8px;border-radius:99px}
.flow-note{font-size:13px;color:var(--text-2)}
.quote-big{font-size:clamp(22px,2.8vw,32px);font-weight:700;line-height:1.3;letter-spacing:-.01em;max-width:34ch}
.quote-big em{font-style:normal;color:var(--orange-ink)}
.vsteps{list-style:none;margin:0;padding:0;display:grid;gap:0;max-width:760px;counter-reset:v}
.vsteps li{position:relative;padding:0 0 28px 64px}
.vsteps li::before{counter-increment:v;content:counter(v);position:absolute;left:0;top:0;width:40px;height:40px;border-radius:50%;background:var(--pale-blue);display:grid;place-items:center;font-weight:800}
.vsteps li::after{content:"";position:absolute;left:19px;top:44px;bottom:4px;width:2px;background:var(--warm-gray)}
.vsteps li:last-child::after{display:none}
.vsteps b{display:block;font-size:19px;margin:6px 0 4px}.vsteps span{color:var(--text-2)}

/* Пакет: карточка продукта */
.pcard{background:var(--white);border:2px solid var(--lamp-orange);border-radius:var(--r-lg);padding:28px;display:grid;gap:14px;min-width:0}
.pcard .tagline{font-size:13px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--orange-ink)}
.pcard .big{font-size:clamp(40px,5vw,56px);font-weight:800;letter-spacing:-.03em;line-height:1;font-variant-numeric:tabular-nums}
.pcard .terms{display:flex;flex-wrap:wrap;gap:8px}
.pcard .terms span{background:var(--warm-neutral);border-radius:99px;padding:6px 12px;font-size:13px;font-weight:600}
.pcard ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.pcard li{display:flex;gap:10px;font-size:15px}
.pcard li::before{content:"✓";flex-shrink:0;width:20px;height:20px;border-radius:50%;background:var(--soft-orange);display:grid;place-items:center;font-size:11px;font-weight:800}
.pcard .btn{justify-self:stretch;justify-content:center}

/* Фото-блоки */
.split{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center}
.split img{width:100%;display:block;border-radius:var(--r-lg);aspect-ratio:4/3;object-fit:cover}
.split .txt{display:grid;gap:16px;min-width:0}
.stats{display:flex;flex-wrap:wrap;gap:16px 36px;margin-top:8px}
.stats div{font-size:14px;color:var(--text-2)}.stats b{display:block;font-size:34px;font-weight:800;color:var(--graphite);font-variant-numeric:tabular-nums}
.person{display:grid;grid-template-columns:220px 1fr;gap:32px;align-items:center;background:var(--white);border-radius:var(--r-lg);padding:24px}
.person img{width:100%;aspect-ratio:4/5;object-fit:cover;object-position:50% 10%;border-radius:var(--r-md);display:block}
.person .role{font-size:14px;font-weight:700;color:var(--orange-ink)}
.person h3{font-size:26px;font-weight:800;margin:6px 0 10px}
.person p{color:var(--text-2);max-width:56ch}
@media (max-width:860px){.split{grid-template-columns:1fr;gap:28px}.person{grid-template-columns:1fr}.person img{max-width:240px}}

.map{display:grid;gap:8px;margin-top:28px}
.map-row{display:grid;grid-template-columns:1fr 32px 1fr;gap:12px;align-items:center}
.map-row .f{background:#FBE9E7;border-radius:var(--r-sm);padding:12px 14px;font-size:14px}
.map-row .t{background:var(--white);border-radius:var(--r-sm);padding:12px 14px;font-size:14px;font-weight:600}
.map-row .ar{text-align:center;font-weight:800;color:var(--orange-ink)}
.map-head{display:grid;grid-template-columns:1fr 32px 1fr;gap:12px;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--text-2)}
@media (max-width:600px){.map-row,.map-head{grid-template-columns:1fr}.map-row .ar{display:none}.map-head span:nth-child(2){display:none}}
.final{text-align:left}
.final .cta-row{margin-top:8px}
